fn is_prime(n: i64) -> bool {
    if n <= 1 {
        return false;
    }
    let mut i = 2;
    while i * i <= n {
        if n % i == 0 {
            return false;
        }
        i += 1;
    }
    true
}

fn is_t_prime(x: i64) -> bool {
    let root = (x as f64).sqrt() as i64;
    if root * root == x && is_prime(root) {
        true
    } else {
        false
    }
}

